// === Tab: ease ===
const ease = {
    inSine: (x) => 1 - Math.cos((x * Math.PI) / 2),
    outSine: (x) => Math.sin((x * Math.PI) / 2),
    inOutSine: (x) => -0.5 * (Math.cos(Math.PI * x) - 1),
    inQuad: (x) => x * x,
    outQuad: (x) => 1 - (1 - x) * (1 - x),
    inOutQuad: (x) => (x < 0.5 ? 2 * x * x : -1 + (4 - 2 * x) * x),
    inCubic: (x) => x * x * x,
    outCubic: (x) => 1 - Math.pow(1 - x, 3),
    inOutCubic: (x) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2),
    inQuart: (x) => x * x * x * x,
    outQuart: (x) => 1 - Math.pow(1 - x, 4),
    inOutQuart: (x) => (x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2),
    inQuint: (x) => x * x * x * x * x,
    outQuint: (x) => 1 - Math.pow(1 - x, 5),
    inOutQuint: (x) => (x < 0.5 ? 16 * x * x * x * x * x : 1 - Math.pow(-2 * x + 2, 5) / 2),
    inExpo: (x) => (x === 0 ? 0 : Math.pow(2, 10 * x - 10)),
    outExpo: (x) => (x === 1 ? 1 : 1 - Math.pow(2, -10 * x)),
    inCirc: (x) => 1 - Math.sqrt(1 - x * x),
    outCirc: (x) => Math.sqrt(1 - Math.pow(x - 1, 2)),
    inOutCirc: (x) =>
        x < 0.5
            ? (1 - Math.sqrt(1 - Math.pow(2 * x, 2))) / 2
            : (Math.sqrt(1 - Math.pow(-2 * x + 2, 2)) + 1) / 2,
    outSquareRoot: (x) => Math.sqrt(x),
    inSquareRoot: (x) => 1 - Math.sqrt(1 - x),
    linear: (x) => x,
}

// === Tab: cell ===
let celldr = {
	tri: function (s, p) {
		triangle(0, 0, s * p, 0, 0, s * p )
	},
	halfCirc: function (s, p) {
		let p1 = constrain(map(p, 0, 0.75, 0, 1), 0, 1)
		let p2 = constrain(map(p, 0.25, 1, 0, 1), 0, 1)
		arc(s / 2, 0, s, s * p1, 0, PI)
		arc(s / 2, s, s, s * p2, PI, 0)
	},
	halfCircStack: function(s, p) {
		let p1 = constrain(map(p, 0, 0.75, 0, 1), 0, 1)
		let p2 = constrain(map(p, 0.25, 1, 0, 1), 0, 1)
		let half = map(p2, 0, 1, s * 0.25, s * 0.5)
		arc(s / 2, half,  s, s * p2, 0, PI)
		arc(s / 2, 0,     s, s * p1, 0, PI)
	},
	circle: function (s, p) {
		circle(s / 2, s / 2, s * p)
	},
	circle_line: function(s, p) {
		let lw = s * 0.2 
		strokeWeight(lw)
		let radius = s * 0.8
		circle(s / 2, s / 2, radius * p)
	},
	qCirc: function(s, p) {
		arc(0, 0, s * 2 * p, s * 2 * p, 0, PI * 0.5)
	},
	qCirc_line: function(s, p) {
		let lw = s * 0.2
		strokeWeight(lw)
		this.qCirc(s - lw / 2, p)
	},
	dots: function(s, p) {
		let grid = 2 
		let step = s / grid
		let stagger = 0.5 / (grid * grid)
		let s2 = s * 0.3
		let i = 0
		for (let x = 0; x < grid; x++) {
			for (let y = 0; y < grid; y++) {
				if (p >= stagger * i) {
					let p2 = map(p, stagger * i, stagger * i + 0.5, 0, 1)
					p2 = constrain(p2, 0, 1)
					let cx = step * (x + 0.5)
					let cy = step * (y + 0.5) 
					circle(cx, cy, s2 * p2)
				}
				i++
			}
		}
	},
	lines: function(s, p) {
		let lw = s * 0.15
		strokeWeight(lw) 
		let steps = 4
		let step = s / steps
		let stagger = 0.4 / steps
		for (let i = 0; i < steps; i++) {
			if (p >= stagger * i) {
				let p2 = map(p, stagger * i, stagger * i + 0.6, 0, 1)
				line(0, step * (i + 0.5), s * p2, step * (i + 0.5))
			}
		}
	},
	leaf: function(s, p) {
		let ctx = drawingContext
		ctx.beginPath() 
		ctx.arc(s / 2 * p,  s / 2 * p, s * 0.5 * p, -PI * 0.5, PI)
		ctx.lineTo(0,0)
		ctx.closePath()
		ctx.fill()
	}
}

// === Tab: params ===
let palettes = [
	['#533a71', '#454a96', '#6184d8', '#50c5b7', '#9cec5b', '#f0f465', '#ff4a1c', '#ed254e'],
	['#dc5132', '#a46589', '#7a82b8', '#8ad0a6', '#c4f0a8', '#a0bb07', '#ffcf33', '#ec9f05'],
	['#874286', '#856596', '#f9c8ce', '#a8d7a8', '#b6cccc',  '#7a7eb8', '#fc814a']
]

const DUR = {
	in: 700,
	out: 700, 
	wait: 2200, 
	enter: 2000
}

const SIDES = 15 

const FREQ_SHAPE = 0.1
const FREQ_COLOR = 0.1 

// must be key of ease object
const EASE_IN = 'outCubic'
const EASE_OUT = 'outSine'
const EASE_ENTER = 'outQuad'

// === Tab: utils ===
const indexToPoint = (index, sides) => {
	if (index < 0 || index >= sides * sides) return { x: -1, y: -1 }
	return { x: index % sides, y: Math.floor(index / sides)}
}

const pointToIndex = (x, y, sides) => {
	if (x < 0 || x >= sides || y < 0 || y >= sides) return -1
	return y * sides + x
}


// === Tab: sketch ===
let cellStages = ['in', 'wait', 'out']
let styleOpts = []
let palette
let bg
let cells = []
let m
let lastTime = null
let noiseIndex = 0
let noiseIndexGrid = 0
let addTimeLast = 0
let addProgress = 0
let addIndex = 0
let seed

function setup() {
	createCanvas(windowWidth, windowHeight);
	createPattern()
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight)
	m = max(width, height) * 0.9
}

function mouseClicked() {
	createPattern()
}

function draw() {
	let t = millis()
	if (!lastTime) lastTime = t
	let delta = t - lastTime
	lastTime = t

	addProgress = min(1, addProgress + delta / DUR.enter)
	let progressEase = ease[EASE_ENTER](addProgress)
	addIndex = round(progressEase * (cells.length - 1))

	let cellSize = m / SIDES
	cellSize = ceil(cellSize)
	m = cellSize * SIDES

	push()
	translate((width - m) / 2, (height - m) / 2)
	background(bg)

	for (let i = 0; i <= min(addIndex, cells.length - 1); i++) {
		let cell = cells[i]
		let x = cell.nx * cellSize
		let y = cell.ny * cellSize
		let s = cell.s * cellSize
		if (cell.stage === 'pre') {
			updateCell(cell, t)
		}

		if (cell.p >= 1) {
			cell.stage = cellStages[(cellStages.indexOf(cell.stage) + 1) % 3]
			cell.p = 0
			if (cell.stage === 'in') {
				updateCell(cell, t)
			}
		}
		let dur = DUR[cell.stage]
		cell.p = min(1, cell.p + delta / dur)

		push()
		beginClip()
		rect(x, y, s, s)
		endClip()
		if (cell.style.includes('line')) {
			stroke(cell.color)
			noFill()
		} else {
			noStroke()
			fill(cell.color)			
		}

		let p = 0 
		if (cell.stage === 'wait') {
			p = 1
		} else if (cell.stage === 'in') {
			p = ease[EASE_IN](cell.p)
		} else if (cell.stage === 'out') {
			p = ease[EASE_OUT](1 - cell.p)
		}
		cellTransform(x, y, s, cell.rot, p)
		celldr[cell.style](s, p, cell.color)
		pop()
	}
	pop()
}

function createPattern() {
	m = max(width, height) * 0.9
	lastTime = null
	noiseIndex = 0 
	noiseIndexGrid = 0
	palette = shuffle([...random(palettes)])
	bg = palette.pop()
	styleOpts = shuffle(Object.keys(celldr))
	seed = floor(random(1000))
	noiseSeed(++seed)

	addTimeLast = 0
	addProgress = 0
	addIndex = 0

	let cellMap = Array.from({ length: SIDES * SIDES }, () => null)
	cells = []
	let i = 0 

	while (i < cellMap.length) {
		if (cellMap[i] !== null) {
			i++
			continue
		}

		let {x, y} = indexToPoint(i, SIDES) 
		let cell = { nx: x, ny: y, s: 1, rot: 0, stage: 'pre' }
		cellMap[i] = cell
		cells.push(cell)
		i++
	}

	cells = cells.sort((a, b) => {
		let diff = a.ny + a.nx - (b.ny + b.nx) 
		return diff
	})
}

function updateCell(cell, t) {
	noiseIndex++
	if (noiseIndex >= SIDES * SIDES) {
		noiseIndex = 0 
		noiseIndexGrid++
	}
	let n = noise(cell.nx * FREQ_SHAPE, cell.ny * FREQ_SHAPE, noiseIndexGrid)
	let ns = floor(n * styleOpts.length * 2)
	cell.style = styleOpts[ns % styleOpts.length]

	let rotOptions = [0, PI * 0.5, PI, PI * 1.5]
	let nr = floor((n + random(0.3)) * 4)
	cell.rot = rotOptions[nr % rotOptions.length]

	let nColor = noise(cell.nx * FREQ_COLOR, cell.ny * FREQ_COLOR, noiseIndexGrid)
	nColor = floor(nColor * palette.length * 2)
	cell.color = palette[nColor % palette.length]
	cell.p = 0 
	cell.stage = 'in'
}

function cellTransform(x, y, s, rot, p) {
	translate(x + s / 2,y + s / 2)
	rotate(rot)
	translate(-s / 2, -s / 2)
}



